(()=>{const el=document.getElementById('model');if(!el)return;const base=new URL('.',document.currentScript.src);const load=name=>new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=new URL(name,base);s.onload=resolve;s.onerror=reject;document.body.append(s)});const start=()=>requestAnimationFrame(()=>requestAnimationFrame(()=>{(async()=>{try{for(const file of ['three.min.js','GLTFLoader.js','DRACOLoader.js','hologram.js'])await load(file)}catch{el.querySelector('.model-loader')?.remove();el.setAttribute('aria-busy','false')}})()}));if(document.readyState==='complete')start();else addEventListener('load',start,{once:true})})();